/* Intermediate4 · Preserve invoices, price object granularity and verify archive access. */
(function(){
  const N=AG.aws.n,NOW='2026-10-26T00:00:00Z',UNTIL='2033-10-26T00:00:00Z',ROLE='arn:aws:iam::123456789012:role/shop-replication';
  const LC=()=>({Rules:[{ID:'archive-large-logs',Status:'Enabled',Filter:{And:{Prefix:'logs/aggregated/',ObjectSizeGreaterThan:131071}},Transitions:[{Days:30,StorageClass:'STANDARD_IA'},{Days:180,StorageClass:'GLACIER'}]},{ID:'noncurrent-cleanup',Status:'Enabled',Filter:{Prefix:'logs/'},NoncurrentVersionTransitions:[{NoncurrentDays:30,StorageClass:'STANDARD_IA'}],NoncurrentVersionExpiration:{NoncurrentDays:365}},{ID:'abort-incomplete',Status:'Enabled',Filter:{Prefix:'logs/'},AbortIncompleteMultipartUpload:{DaysAfterInitiation:7}}]});
  const LOCK=()=>({ObjectLockEnabled:'Enabled',Rule:{DefaultRetention:{Mode:'COMPLIANCE',Years:7}}}),RETENTION=()=>({Mode:'COMPLIANCE',RetainUntilDate:UNTIL});
  const REPL=()=>({Role:ROLE,Rules:[{ID:'invoices-crr',Priority:1,Status:'Enabled',Filter:{Prefix:'invoices/'},DeleteMarkerReplication:{Status:'Disabled'},Destination:{Bucket:'arn:aws:s3:::shop-invoices-dr'}}]});
  const IT=()=>({Id:'unknown-media',Status:'Enabled',Filter:{Prefix:'photos/'},Tierings:[{Days:180,AccessTier:'ARCHIVE_ACCESS'},{Days:365,AccessTier:'DEEP_ARCHIVE_ACCESS'}]});
  function seed(){const base=name=>({name,region:'ap-south-1',public:false,encryption:true,bpa:{BlockPublicAcls:true,IgnorePublicAcls:true,BlockPublicPolicy:true,RestrictPublicBuckets:true},versioning:true,objects:[]});return {region:'ap-south-1',now:NOW,canBypassGovernance:true,roles:[{name:'shop-replication',replication:{trust:'s3.amazonaws.com',source:'shop-invoices',destination:'shop-invoices-dr',readRetention:true,readLegalHold:true}}],buckets:[{...base('shop-invoices'),versions:{'invoices/INV-301.pdf':[{versionId:'v-keep',body:'original invoice INV-301',etag:'"invoice-301"',size:2097152,storageClass:'STANDARD',lastModified:NOW}]}},{...base('shop-invoices-dr'),region:'us-east-1',versioning:undefined,versions:{}},{...base('shop-logs'),versions:{'logs/raw/event.json':[{versionId:'v-raw',body:'raw log',size:8192,storageClass:'STANDARD'}],'logs/aggregated/day.parquet':[{versionId:'v-aggregate',body:'aggregated logs',size:10485760,storageClass:'STANDARD'}]}},{...base('shop-media'),versions:{'photos/kurta.jpg':[{versionId:'v-photo',body:'public product image',size:1048576,storageClass:'INTELLIGENT_TIERING'}]}}]};}
  const bucket=(s,name)=>(s.account.buckets||[]).find(b=>b.name===name),version=(s,name,key,id)=>{const b=bucket(s,name),vs=b&&(b.versions||{})[key];return Array.isArray(vs)?vs.find(v=>v.versionId===id):null;};
  function eq(a,b){if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object')return false;const ak=Object.keys(a).sort(),bk=Object.keys(b).sort();return ak.length===bk.length&&ak.every((k,i)=>k===bk[i]&&eq(a[k],b[k]));}
  function lifecycle(s){const b=bucket(s,'shop-logs'),rows=b&&b.lifecycle&&b.lifecycle.Rules,strip=r=>{const {ID,...rest}=r;return rest;};return Array.isArray(rows)&&rows.length===3&&b.lifecycleMinimum==='all_storage_classes_128K'&&LC().Rules.every(e=>rows.some(r=>eq(strip(r),strip(e))));}
  function protectedInvoice(s){const b=bucket(s,'shop-invoices'),v=version(s,'shop-invoices','invoices/INV-301.pdf','v-keep');return !!b&&b.versioning&&eq(b.objectLock,LOCK())&&!!v&&v.retention&&v.retention.Mode==='COMPLIANCE'&&new Date(v.retention.RetainUntilDate)>=new Date(UNTIL);}
  function replication(s){const a=bucket(s,'shop-invoices'),b=bucket(s,'shop-invoices-dr');return !!a&&a.versioning&&!!b&&b.versioning&&b.region==='us-east-1'&&b.objectLock&&b.objectLock.ObjectLockEnabled==='Enabled'&&a.replication&&a.replication.Role===ROLE&&Array.isArray(a.replication.Rules)&&a.replication.Rules.length===1&&a.replication.Rules[0].Status==='Enabled'&&a.replication.Rules[0].Filter&&a.replication.Rules[0].Filter.Prefix==='invoices/'&&a.replication.Rules[0].Destination&&a.replication.Rules[0].Destination.Bucket==='arn:aws:s3:::shop-invoices-dr'&&a.replication.Rules[0].DeleteMarkerReplication&&a.replication.Rules[0].DeleteMarkerReplication.Status==='Disabled';}
  function tiering(s){const b=bucket(s,'shop-media'),v=version(s,'shop-media','photos/kurta.jpg','v-photo');return !!b&&eq((b.intelligentTiering||{})['unknown-media'],IT())&&!!v&&v.storageClass==='INTELLIGENT_TIERING';}
  function preserved(s){const a=seed();return (s.account.buckets||[]).length===4&&a.buckets.every(original=>{const b=bucket(s,original.name);return !!b&&!b.public&&b.encryption&&b.bpa&&['BlockPublicAcls','IgnorePublicAcls','BlockPublicPolicy','RestrictPublicBuckets'].every(k=>b.bpa[k]===true)&&Object.entries(original.versions).every(([key,rows])=>{const current=(b.versions||{})[key];return Array.isArray(current)&&current[0]&&current[0].versionId===rows[0].versionId&&rows.every(v=>{const kept=current.find(x=>x.versionId===v.versionId);return !!kept&&kept.body===v.body&&kept.size===v.size&&!kept.deleteMarker;});});})&&(s.account.roles||[]).some(r=>r.name==='shop-replication'&&eq(r.replication,a.roles[0].replication));}
  const file=v=>({content:JSON.stringify(v,null,2)});
  const SOLUTION=['aws s3api put-bucket-versioning --bucket shop-invoices-dr --versioning-configuration Status=Enabled','aws s3api put-bucket-lifecycle-configuration --bucket shop-logs --lifecycle-configuration file://lifecycle.json --transition-default-minimum-object-size all_storage_classes_128K','aws s3api put-object-lock-configuration --bucket shop-invoices --object-lock-configuration file://lock-seven-years.json','aws s3api put-object-retention --bucket shop-invoices --key invoices/INV-301.pdf --version-id v-keep --retention file://existing-invoice-retention.json','aws s3api put-object-lock-configuration --bucket shop-invoices-dr --object-lock-configuration file://dr-lock.json','aws s3api put-bucket-replication --bucket shop-invoices --replication-configuration file://replication.json','aws s3api put-bucket-intelligent-tiering-configuration --bucket shop-media --id unknown-media --intelligent-tiering-configuration file://tiering.json'];
  function plan(k){const size=[10,128,1024,10240,102400][k.size],count=[1e4,1e5,1e6,1e7][k.count],glacier=[30,60,90,180,300][k.glacier],gb=size*1024*count/2**30,eligible=size>=128||k.override===1,ia=Math.max(0,Math.min(365,k.ia)),gd=Math.max(ia,Math.min(365,glacier)),iaDays=gd-ia,glDays=365-gd,baseline=gb*0.023*12;
    const standard=gb*0.023*ia/365*12,iaStorage=Math.max(size,128)*1024*count/2**30*0.0125*iaDays/365*12,glStorage=((size+32)*1024*count/2**30*0.0036+8*1024*count/2**30*0.023)*glDays/365*12,transitions=count/1000*(0.01+0.03),readFraction=k.reads/100,readBytes=gb*readFraction*12,retrieval=readBytes*0.01*(iaDays+glDays)/365+count*readFraction*12/1000*0.05*glDays/365,early=Math.max(0,30-iaDays)/30*Math.max(size,128)*1024*count/2**30*0.0125+Math.max(0,90-glDays)/30*(size+32)*1024*count/2**30*0.0036,total=eligible?standard+iaStorage+glStorage+transitions+retrieval+early:baseline,saving=1-total/baseline,valid=ia>=30&&glacier>=ia+30,noPenalty=size>=128&&early===0,ok=gb>=100&&k.reads>=10&&eligible&&valid&&noPenalty&&saving>=0.50;return {size,count,gb,eligible,baseline,storage:eligible?standard+iaStorage+glStorage:baseline,transitions:eligible?transitions:0,retrieval:eligible?retrieval:0,early:eligible?early:0,total,saving,valid,noPenalty,ok};}
  function Q(q,correct,wrong,answer,explain,domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain,domain};}
  const table=html=>'<div class="tbl-wrap">'+html+'</div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>';
  AG.registerLevels('intermediate',[{
    id:'s3adv',icon:'🪣',title:'S3 Advanced: chhoti files ka bill, 7 saal ki retention aur DR ka saboot',badge:'Storage Strategist',
    hook:{when:'ShopKaro · teen saal ke invoices/logs/photos · course ki kahani (fictional)',title:'"Archive sasta tha. Phir chhote logs ka bill aur delete ka khatra kyun badha?"',text:'Priya ke course scenario mein storage ka bill lagbhag ₹40,000/mahina se upar chala gaya. Ravi saare 8 KB logs archive karna chahta hai. Ek purane intern ne files delete kar di thi; versioning ne invoices wapas dila diye. Par finance ki zaroorat aur sakht hai: chune hue invoice versions 7 saal tak hamesha ke liye delete na hon. Storage class, data retention aur check ki hui DR copy: teen alag faisle hain. Koi khaas kanoon maana nahi gaya.'},
    objectives:['<b>Kharche ka faisla</b>: 7 general-purpose classes, unke minimums aur request/retrieval charges compare karo','<b>File ka size</b>: chhoti files ko transition se pehle jodo; aaj ka 128 KB lifecycle default samjho','<b>Bachav</b>: aage ke liye default retention vs pehle se bane version par compliance/legal hold','<b>Replication</b>: versioning, role, destination lock, nayi vs purani files aur RTC ka scope','<b>Restore/performance</b>: archive file padhna, temporary copy, multipart aur prefix scale','<b>Saboot</b>: state se config theek karo; asli lab mein protection aur restore hue bytes check karo'],
    steps:[
      {q:'Storage ke daam ke saath kaun se minimums aur retrieval charges compare karoge?',analogy:'Warehouse ki shelf ka kiraya sasta ho sakta hai. Par har parcel ki handling, minimum booking aur emergency pickup ka charge alag lagta hai. Sirf shelf ke rate se saal ka bill tay nahi hota.',body:table('<table><tr><th>General-purpose class</th><th>Lagbhag $/GB/mahina, US East pehla tier</th><th>Minimum</th><th>Retrieval</th></tr><tr><td>Standard</td><td>0.023</td><td>Koi minimum time ya size nahi</td><td>ms; per-GB retrieval fees nahi</td></tr><tr><td>Intelligent-Tiering</td><td>0.023 / 0.0125 / 0.004 apne aap badalne wale online tiers</td><td>Koi minimum time nahi; auto-tier ke liye 128 KB se badi file</td><td>Online tiers ms mein; optional archives ke liye restore</td></tr><tr><td>Standard-IA</td><td>0.0125</td><td>30 din; 128 KB ka minimum bill</td><td>ms; lagbhag $0.01/GB padhne par</td></tr><tr><td>One Zone-IA</td><td>0.010</td><td>30 din; 128 KB; sirf ek AZ</td><td>ms; lagbhag $0.01/GB padhne par</td></tr><tr><td>Glacier Instant Retrieval</td><td>0.004</td><td>90 din; 128 KB ka minimum bill</td><td>ms; lagbhag $0.03/GB padhne par</td></tr><tr><td>Glacier Flexible Retrieval</td><td>0.0036</td><td>90 din; har file par 40 KB extra metadata</td><td>Expedited aam taur par 1–5 min; Standard 3–5 ghante; Bulk 5–12 ghante</td></tr><tr><td>Glacier Deep Archive</td><td>0.00099</td><td>180 din; har file par 40 KB extra metadata</td><td>Standard aam taur par 12 ghante; Bulk 48 ghante</td></tr></table>'),points:['Daam 2025–26 ke us-east-1 list rates se lagbhag hain, ₹88 = $1. Region, tier, requests aur tax se bill badalta hai. Aaj ke public price catalog check kiye gaye; planner budget ka model hai, AWS ka bill nahi.','Flexible/Deep ka metadata: 8 KB Standard rate par + 32 KB archive rate par. Glacier Instant ka 128 KB minimum alag niyam hai. Minimum time se pehle delete ya transition kiya, toh bache din ka storage charge phir bhi lag sakta hai.','One Zone-IA sirf aise data ke liye jo dobara ban sakta hai ya secondary hai, aur AZ jaane ka khatra manzoor hai. Storage class se WORM ya compliance nahi milta. Express One Zone directory bucket aur ek AZ wala tez design hai; yeh lambe archive se alag choice hai.'],asli:'Kaam: bins game mein "teen mahine mein ek baar, par ms mein" wali zaroorat ko Glacier Instant se jodo. Flexible/Deep mein restore chahiye; badi files ya capacity ki wajah se aam time se zyada lag sakta hai.'},
      {q:'File kab padhi jaayegi pata na ho, toh Intelligent-Tiering kya apne aap karta hai?',analogy:'Warehouse ka clerk har parcel ka aakhri pickup note karta hai. Jo maal use nahi hua, use sasti shelf par shift kar deta hai. Par har chhote label par clerk ki fees lena bekaar hai.',body:'<p>Intelligent-Tiering ke online tiers: 30 din tak koi access nahi → Infrequent; 90 din → Archive Instant, phir bhi ms mein padh sakte ho. Optional Archive Access (kam se kam 90 din) aur Deep Archive Access (kam se kam 180 din) on karoge, toh restore ki der manzoor karni padegi.</p>',points:['Monitoring/automation lagbhag $0.0025 har 1,000 eligible files/mahina. Retrieval fees nahi; par expedited restore, requests, transfer aur optional features ke charges dekho. Tier badalne ki koi extra request fees nahi.','128 KB se chhoti files Frequent tier mein hi rehti hain: na monitoring charge, na auto-tier ki bachat. Chhoti files ke workload mein aankh band karke Intelligent-Tiering mat chuno.','Bucket ki Intelligent-Tiering configuration sirf optional archive thresholds set karti hai; Standard files apne aap convert nahi hoti. Files ko PUT/COPY/lifecycle se INTELLIGENT_TIERING class mein alag se daalna padta hai.','"Archive se padhne mein kitni der chalegi" pata na hona alag faisla hai. Pattern pata nahi, toh online auto tiers theek hain; owner ki manzoori ke bina dheeme archives on karna khatarnaak hai.'],asli:'Kaam: main mission mein media file pehle se INTELLIGENT_TIERING mein hai. cat tiering.json mein photos/ prefix aur 180/365 din ke optional archive thresholds dekho; yeh config storage class badalne ka daava nahi karta.'},
      {q:'Lifecycle se bill kab kam hota hai, aur chhoti files ka jaal kab hai?',analogy:'Courier har packet ko cold warehouse bhejne ki handling fees leta hai. Laakhon chhote packets ko bade sealed batches mein pack karna sasta pad sakta hai. Par batch banane se wapas nikaalne ka tareeka bhi badalta hai.',body:table('<table><tr><th>Lifecycle action</th><th>Kaam</th><th>Limit</th></tr><tr><td>Current transitions</td><td>Jode hue logs 30 din par → IA, 180 din par → Flexible</td><td>Request charges, minimum time, restore ki der manzoor hai ya nahi</td></tr><tr><td>Noncurrent transitions/expiration</td><td>Purane versions ka alag aging/cleanup</td><td>Sirf current expiry se version history nahi hatti</td></tr><tr><td>Abort incomplete multipart</td><td>7 din baad bekaar upload parts hatao</td><td>Alag prefix rule; poori files delete nahi karta</td></tr></table>'),points:['September 2024 se naye ya update hue lifecycle mein default yeh hai: 128 KB se chhoti files kisi bhi class mein transition nahi hoti. Saaf object-size filter is default ko badal sakta hai; purane configs alag ho sakte hain. Yeh mat maano ki naya default har 8 KB log ko archive kar dega.','Lagbhag har 1,000 transition requests par: IA $0.01, Glacier Instant $0.02, Flexible $0.03, Deep $0.05. 10 lakh files Standard → IA → Flexible = storage/reads se pehle lagbhag $40 handling; 1 crore files = $400.','Ek rule ki chain mein source class ka minimum gap maanna padta hai. Expiration ya doosre rule se jaldi move hua, toh minimum-time ka charge phir bhi lag sakta hai. Lifecycle apne time par chalta hai; yeh exact timer nahi.','Retention aur query ka pattern allow kare, toh logs ko jodo/compress karo. Index aur nikaalne ka tareeka aur audit ki zarooratein bani rehni chahiye; data kho kar size badalna bachat nahi. Retention se bache versions lock khatam hone se pehle delete nahi ho sakte.'],asli:'Kaam: planner mein ≥100 GiB data aur har mahine ≥10% files padhna rakho, phir 10 MiB ke batches try karo. Mission ka lifecycle logs/aggregated/ ko ObjectSizeGreaterThan 131071 ke saath target karta hai; kachche 8 KiB logs transition prefix se bahar rehte hain.'},
      {q:'Replication config ke baad asli DR copy ka saboot kya hoga?',analogy:'Courier ka contract sign karna parcel pahunchne ka saboot nahi. Dono warehouses ke version labels, access badges aur delivery ka status chahiye.',body:'<pre>Source versioning + destination versioning\n + S3 par bharosa karne wala replication role, chhoti permissions\n + enabled prefix rule → nayi files ki replication (asynchronous)\n + destination par version/data/status check\nPurani files → alag Batch Replication workflow</pre>',points:['SRR = same region mein copy; CRR = doosre region mein copy. Cross-region se failure alag-alag rehta hai, par data residency ke niyam, ownership aur KMS permissions ka review zaroori hai; zyada deshon mein copy apne aap compliant nahi.','Default live replication rule ke baad ki nayi eligible writes cover karti hai, purana backfill nahi. Delete marker ki replication optional hai; version-ID wale deletes aur lifecycle expiration ke marker alag behave karte hain. Replica apne aap ek alag, na badalne wala backup nahi, jab tak retention/access ka design use bachaaye nahi.','Source par Object Lock on hai, toh destination par bhi on chahiye. Role ko replication ki permissions ke alawa GetObjectRetention aur GetObjectLegalHold bhi chahiye. Source ki retention metadata copy hoti hai; agla card fixed retention samjhata hai.','Optional S3 RTC SLA aur shartein poori hon toh 99.99% nayi files 15 minute mein copy karta hai. Yeh synchronous zero-RPO nahi, aur har file ki guarantee nahi. Replication metrics/status/failures dekho aur restore ke baad app ka behaviour check karo.'],asli:'Kaam: put-bucket-replication se pehle destination par versioning on karo. Simulator sirf config ki zarooratein check karta hai, replica copy ka daava nahi. Moto lab mein rule save hua par destination khaali raha.'},
      {q:'7 saal ke WORM mein default retention, pehle se bana version aur legal hold: farak kya hai?',analogy:'Naye invoices par lagne wale automatic seal rule se purani bina seal ki file bachti nahi. Purani file par naam le kar alag seal lagana padta hai. Court ka hold fixed expiry se alag, ek "ruk jao" flag hai.',body:table('<table><tr><th>Control</th><th>Kya bachata hai</th><th>Debug ki detail</th></tr><tr><td>Bucket default retention</td><td>Naye versions ko chuna hua time milta hai</td><td>Purane versions ko alag/batch retention chahiye</td></tr><tr><td>Governance retention</td><td>Zyaadatar users protected version hamesha ke liye delete nahi kar sakte</td><td>Allowed bypass permission + saaf flag se override ho sakta hai</td></tr><tr><td>Compliance retention</td><td>Active retention mein koi bhi, root bhi, version delete ya time kam nahi kar sakta</td><td>Governance bypass flag kaam nahi karta</td></tr><tr><td>Legal hold</td><td>Alag se ON rehta hai jab tak allowed insaan OFF na kare</td><td>Governance bypass hold nahi hataata</td></tr></table>'),points:['Object Lock ke liye versioning chahiye; ab pehle se versioned general-purpose bucket par bhi on ho sakta hai. Ek baar on hua, toh Object Lock band nahi hota aur versioning suspend nahi hoti. Protected data ki encryption key bhi milti rehni chahiye.','Protection ek version par lagti hai. Simple DELETE delete marker jod kar latest key chhupa sakta hai; protected version bacha rehta hai. Naya PUT ek aur version banata hai; purane protected version ko wahin overwrite nahi karta.','Course ki fixed retention fixture date 2026-10-26 se 7 saal, yaani 2033-10-26 tak hai. Pehle se bana v-keep alag se retain kiya gaya; default Years=7 aage ke invoices sambhalta hai. Finance ki zaroorat se koi kanoon maana nahi gaya.','Asli lab 1 din ki governance aur cleanup bypass use karti hai, 7 saal ki compliance nahi. AWS mein ab variable/event retention ke options bhi hain; yeh exercise jaan-boojh kar fixed retention aur legal hold par focus karti hai.'],asli:'Kaam: mission mein cat lock-seven-years.json, phir existing-invoice-retention.json compare karo. Purane version ki retention chhodi, toh bucket default sahi dikhne par bhi jeet nahi milegi.'},
      {q:'Archive restore aur upload performance ka practical plan kya hai?',analogy:'Cold warehouse se padhne ke liye thodi der ki copy milti hai; asli parcel cold storage mein hi reh sakta hai. Bada shipment hisson mein bhejna retry layak hai; ek hissa fail ho toh poora shipment dobara nahi bhejna padta.',body:'<p>GLACIER/DEEP_ARCHIVE file ko restore se pehle GET karoge toh InvalidObjectState aa sakta hai. restore-object request bhejo, head-object ka Restore metadata tab tak dekho jab tak ongoing-request=false na ho, phir exact version padho aur bytes check karo. Temporary copy expire hone ke baad asli archive bacha rehta hai; class hamesha ke liye badalni ho toh alag review ki hui copy chahiye.</p>',points:['Glacier Instant turant padha ja sakta hai; usme archive restore nahi hota. Flexible/Deep ke tiers ka time, fees aur capacity alag hai; Deep Archive mein expedited nahi milta. Asli der minutes/ghante hoti hai; simulator likhe hue poll steps use karta hai.','AWS har partitioned prefix par kam se kam 3,500 PUT/COPY/POST/DELETE aur 5,500 GET/HEAD requests/second likhta hai. Scaling dheere-dheere hoti hai; parallel prefixes/requests, retry/backoff aur byte-range reads madad karte hain. Yeh poore bucket ki pakki maximum limit nahi.','Lagbhag 100 MB se badi file par multipart socho. Ek PUT ki limit 5 GB hai; usse badi file ke liye multipart zaroori. December 2025 se maximum object size 50 TB likha hai (exact limit part size/count se tay hoti hai); purani 5 TB wali limit ab purani hai.','S3 Transfer Acceleration door se upload ko AWS edge ke raaste tez kar sakta hai; asli speed aur extra charge test karo. CDN se download cache karna aur upload tez karna alag tools hain.'],asli:'Kaam: interview ke restore mission mein koi nakli "restore-completed" waiter nahi hai. Model mein restore request, do head-object polls, phir get-object se memory wale output mein file padhna hai; asli version/body check hota hai. AWS ka asli time model nahi hota.'},
      {q:'Upload hone par event, aur shared bucket mein har app ka alag access: design kaise karein?',analogy:'Warehouse mein maal aane ki ghanti ek event signal hai; maal process hone ki guarantee nahi. Har team ka alag counter usko andar aane ka raasta deta hai, poora warehouse copy kiye bina.',body:table('<table><tr><th>Zaroorat</th><th>Kya chuno</th><th>Limit</th></tr><tr><td>Upload ke baad file process karo</td><td>S3 notification → Lambda function, SNS topic ya SQS queue; EventBridge integration</td><td>Duplicate ya ulte order mein aa sakta hai; idempotent processor aur permissions</td></tr><tr><td>Shared bucket mein har app ka alag policy raasta</td><td>S3 access point, chahe toh sirf VPC se</td><td>Bucket policy/IAM bhi lagte hain; apne aap public/private nahi badalta</td></tr><tr><td>Purani files ko process/copy karna</td><td>Inventory + Batch Operations/Batch Replication</td><td>Live notification/replication rule purana backfill nahi karta</td></tr></table>'),points:['Source event aur naye output ke prefixes alag rakho. Processor usi event prefix mein output likhe, toh baar-baar chalne wala kaam aur kharcha ban sakta hai. Queue/function ki details agle levels mein banengi.','Duplicate se bachne ke liye bucket/key/version/event IDs use karo. Event notification exactly-once business transaction ya pakka order nahi deta.','Access point policy, bucket ka delegation aur call karne wali identity ki permissions saath mein review karo. VPC-only access point network ka context rokta hai; encrypted content ki privacy ke liye phir bhi sahi permission chahiye.'],asli:'Interview ka agla sawaal: ek shared bucket mein har app ka access chahiye, toh kya har app ko admin bucket policy deni padegi? Nahi. Scoped access point + matching bucket/IAM policy + network context review karo.'},
      {q:'Encryption on karne se retention/compliance aur access apne aap theek ho jaate hain?',analogy:'Taale wali almari ki chaabi kiske paas hai, yeh file delete ke niyam aur padhne walon se alag baat hai. Disk encryption sahi chaabi wale ko data de deti hai. Chaabi nasht ho jaaye, toh bachi hui file bhi padh nahi sakte.',body:'<p>Naye S3 uploads default se SSE-S3 se encrypt hote hain. SSE-KMS mein KMS key permissions ka review, audit/control aur request/key ka kharcha judta hai; supported designs mein S3 Bucket Keys KMS requests kam kar sakti hain. Encryption public policy theek nahi karta, na Object Lock ki retention badhata hai.</p>',points:['Customer-managed symmetric KMS key ka automatic rotation khud on karna padta hai; "har key apne aap rotate hoti hai" galat hai. AWS-managed key aur asymmetric/imported key ka behaviour alag hai.','KMS policy, role ki permissions, encryption context aur doosre account/region mein key milna: sab maayne rakhte hain. SSE-KMS files ki replication ke liye alag settings/permissions chahiye; yeh lab retention ko alag dikhane ke liye SSE-S3 use karti hai.','Minimum storage bill, monitoring, transitions, restore requests/data, temporary restore ki storage, replication requests/transfer aur KMS: sab alag meter hain. Ready hone ke liye andaaze ke saath data, permission aur recovery ka asli saboot chahiye.'],asli:'Kaam: planner ka saal ka kul andaaza dekho; storage, har file ke transitions, retrieval aur jaldi hataane ke charges compare karo. Kam se kam 50% bachat mein data, padhne ki demand aur retention/recovery ki shartein bani rehni chahiye.'},
    ],
    myth:[{myth:'Sasti archive class matlab apne aap 80% bachat aur compliance.',sach:'Har file ki transition fees, archive metadata, retrieval aur minimum storage charges maayne rakhte hain. Class chunne se WORM nahi milta; protected version ki retention aur encryption key ka milna alag baatein hain.'},{myth:'7 saal ki default compliance saare purane invoices ko bhi turant lock kar deti hai.',sach:'Bucket default naye versions par lagta hai. Purane invoice version ko alag/batch retention chahiye; fixed mode/date aur protected asli version dekhna padta hai.'},{myth:'Object Lock matlab koi DELETE key ko badal nahi sakta; governance bypass har lock ko hara deta hai.',sach:'Simple DELETE marker jod kar latest key chhupa sakta hai. Protected version bacha rehta hai. Governance permission + flag active compliance ya legal hold ko bypass nahi kar sakte.'},{myth:'Replication rule save hua matlab purani files copy ho gayi, zero RPO aur archive turant padh sakte hain.',sach:'Live rule nayi eligible writes cover karta hai; purane data ke liye Batch Replication chahiye. Asli replicas/status check karo; RTC ka SLA scope hai. Archive ka GET restore poora hone ke baad hi chalta hai.'}],
    playbook:{title:'Kab use karein / kab nahi: kharcha, retention aur recovery',use:['Access ka pattern pata nahi ya badalta hai, aur file eligible size ki hai → online Intelligent-Tiering socho','Pata hai ki kam/teen mahine mein/archive jaisa access hai → latency aur kul kharche se class chuno','Version level par WORM chahiye → review kiya hua fixed compliance/governance/legal hold design','DR copies → versioned, scoped replication + destination par asli check'],avoid:['Har file ka kharcha naape bina chhoti files ko zabardasti archive karna','Akeli, kabhi na dobara banne wali asli file ke liye One Zone-IA','Default retention ko purane data ka backfill maanna, ya replication metadata ko DR ka saboot','Asli AWS ki temporary lab par 7 saal ki compliance, jise turant saaf karna hai'],how:['Data ke bytes, files ki ginti, padhne ki volume, retention aur restore ki deadline likho','Minimum billed size/time, transition/monitor/read fees aur restore copy ka kharcha compare karo','Jahan allowed ho wahan jodo/compress karo; data/read/index ki shartein bachao','Versioning on/check karo, chuna hua bucket default lagao, aur purane versions par alag retention','Destination ke role/lock/KMS ki zarooratein review karo; asli copies aur restore ke bytes dekho'],redflags:['Laakhon 8 KB files, upar se default ko override karta saaf filter','Sirf current version ki expiry; purane versions aur adhoore uploads ka bill chalta rehta hai','Destination par versioning/lock nahi; emulator support nahi karta toh khaali config lautata hai','Delete marker ko data nasht hona samajhna; restore request ko restore poora samajhna'],rule:'Faisla kaise karein: access pata nahi? Eligible Intelligent-Tiering. Access pata hai + ms chahiye? Frequency aur minimums se Standard/IA/Glacier Instant. Ghante chal jaayenge? Deadline aur kharche se Flexible/Deep. WORM? Alag Object Lock version policy. Region recovery? CRR + data/permission ka asli check, sirf rule nahi.'},
    exam:[{cue:'"unknown/changing access"',pick:'Intelligent-Tiering, eligible object size',why:'Online 30/90 din ke tiers; dheeme archives sirf khud on karne par.'},{cue:'"quarterly access but milliseconds"',pick:'Glacier Instant Retrieval',why:'Flexible/Deep jaisa restore nahi; 90 din ka minimum aur retrieval charge.'},{cue:'"lowest archive cost;12/48h acceptable"',pick:'Deep Archive candidate',why:'180 din ka minimum; requests/metadata/restore ka kharcha aur asli deadline phir bhi dekho.'},{cue:'"WORM even root cannot delete"',pick:'Active Object Lock compliance on exact version',why:'Sirf governance nahi; default purane versions ko backfill nahi karta.'},{cue:'"replicate existing objects"',pick:'Batch Replication',why:'Sirf naya live rule purana backfill nahi karta.'},{cue:'"replication within 15 min SLA"',pick:'S3 RTC',why:'SLA/shartein poori hon toh 99.99% eligible nayi files; har jagah zero-RPO ki guarantee nahi.'},{cue:'"object upload>5 GB"',pick:'Multipart upload',why:'Lagbhag 100 MB+ par socho; aaj ki maximum 50 TB likhi hai; purani 5 TB limit purani hai.'},{cue:'"far-away uploads"',pick:'Evaluate Transfer Acceleration',why:'Network ka fayda aur extra kharcha naapo; CDN downloads se alag cheez hai.'},{cue:'"process on upload / per-app shared-bucket policy"',pick:'Event notification / access point',why:'Duplicate se safe processing; access point + bucket/IAM policy ka review.'}],
    stages:[
      {type:'dryrun',title:'🔍 Ek invoice: kharche ki class, lock aur aakhir mein recovery',goal:'Har "Agla" click par ek state ka badlav dekho. Compliance delete aur purane version ke scope wale do faislon ka jawaab do.',nodes:[N('user',140,85,{label:'Finance'}),N('s3',470,85,{label:'Invoice v-keep'}),N('lock',820,85,{label:'Compliance lock',icon:'🔒'}),N('s3#ia',470,275,{label:'IA / 30 days'}),N('s3#archive',800,440,{label:'Archive / 365 days'}),N('backup',140,440,{label:'Restore copy'}),N('s3#dr',140,275,{label:'DR version'})],edges:[{from:'user',to:'s3'},{from:'s3',to:'lock'},{from:'s3',to:'s3#ia'},{from:'s3#ia',to:'s3#archive'},{from:'s3',to:'s3#dr'},{from:'s3#archive',to:'backup'}],panels:[{id:'cost',title:'Separate cost meters'},{id:'lock',title:'Version protection / recovery'}],steps:[
        {clock:'day 0',say:'Ek 2 MiB invoice Standard mein upload hua. Fixed compliance retention is version par 2033-10-26 tak hai. Region/date aur data course ke fixtures hain; koi kanoon maana nahi.',flows:[{from:'user',to:'s3',tone:'ok'},{from:'s3',to:'lock',tone:'ok'}],panels:{cost:['Standard lagbhag $0.023/GB/mahina','Requests, keys aur replicas alag'],lock:['Protection exact file version par lagti hai','Bucket default sirf aage ke versions par']}},
        {clock:'day 30',say:'Alag archive policy eligible invoice version ko IA mein bhej sakti hai; retention saath rehti hai. Current/purane version ka lifecycle aur minimum time alag plan karo. Main mission invoice ki retention ko logs cleanup se alag bucket mein rakhta hai.',flows:[{from:'s3',to:'s3#ia',tone:'ok'}],panels:{cost:['Har file par ek transition request','IA: 30 din/128 KB ka minimum bill'],lock:['Class badalne se WORM nahi hatta']}},
        {clock:'day 365',say:'Example ke liye lambe archive ka raasta Flexible Retrieval use karta hai: har file par ek transition + 40 KB metadata. Yahi raasta laakhon 8 KB packets par mehenga pad sakta hai; naya default chhoti files ko chhod deta hai jab tak override na karo.',flows:[{from:'s3#ia',to:'s3#archive',tone:'slow'}],panels:{cost:['8 KB metadata Standard rate par + 32 KB archive rate par','Transition fees aur retrieval phir bhi maayne rakhte hain']}},
        {clock:'delete attempt',say:'Root user retained version ko hamesha ke liye delete karne ki koshish karta hai. Compliance retention abhi active hai. Simple delete marker ka kaam alag hai: woh sirf file ko chhupata hai.',ask:{q:'Active compliance version: kya root + governance bypass flag use hamesha ke liye delete kar sakte hain?',choices:['Nahi; active retention ke dauran compliance na bypass hoti hai, na uska time kam hota hai','Haan; governance bypass flag har compliance lock ko ek aam version mein badal deta hai','Haan; Glacier class sirf metadata rakhti hai, isliye asli retained version delete ho sakta hai','Nahi; Object Lock koi naya version banane ya delete marker jodne hi nahi deta'],answer:0,explain:'Active compliance exact version ko bachati hai; root ya bypass bhi delete nahi kar sakte. Storage class lock nahi hataati. Naye versions/markers ban sakte hain; dikhna aur hamesha ke liye delete hona alag hai.'},panels:{lock:['Protected version delete karne par AccessDenied','Delete marker latest key chhupa sakta hai; version bacha rehta hai']}},
        {clock:'old invoice',say:'Ek aur invoice default retention lagne se pehle ka tha. Sirf default purane version ko peeche jaa kar nahi bachata; retain-until metadata dekh kar alag se lagana padega.',ask:{q:'Bucket default Years 7 sahi hai, par purane version par retention nahi. Kya repair chahiye?',choices:['Purane version par review ki hui compliance retention alag se lagao, phir mode/date dekho','Wait karo, default policy bina kuch kiye saare purane versions ko apne aap bachaa legi','Lifecycle Expiration Days 1 jodo, taaki retained history apne aap dobara ban jaaye','Optional archive tier on karo aur maan lo ki storage class ka naam WORM bana deta hai'],answer:0,explain:'Purane version ko alag/batch retention chahiye. Default naye versions ke liye hai; jaldi expiry file hata deti hai, retention theek nahi karti; archive class lock nahi hai.'},panels:{lock:['Default policy ≠ purane version ki retention']}},
        {clock:'audit restore',say:'Archive invoice ka restore bheja gaya; padhne layak hone tak poll karo, phir exact version/body check karo. DR rule ka metadata pahunchi hui copy nahi; destination ka asli status/bytes alag saboot chahiye.',flows:[{from:'s3#archive',to:'backup',label:'temporary readable copy',tone:'ok'},{from:'s3',to:'s3#dr',label:'async config≠delivery',tone:'slow'}],panels:{cost:['Restore request/data + temporary copy ki storage ka charge lag sakta hai'],lock:['Asli archive/retention bani rehti hai','Restore ka asli time model nahi hua']}},
      ],lesson:'Class ke daam storage aur access ka kharcha sambhalte hain; lock exact version bachata hai; replication/restore ke liye asli data ka saboot chahiye. Koi fixed bachat ya zero-RPO ka vaada nahi.'},
      {type:'flowlab',title:'🎛️ Saal ka kharcha: chhoti files vs kaam ke batches',goal:'≥100 GiB data rakho aur har mahine kam se kam 10% files padhi jaayein. Standard ke mukable saal mein ≥50% bachat dikhao, sahi transition chain ho, aur chhoti files/jaldi hataane ka penalty na ho. Data ya padhne ki demand kam karke jeet nahi milegi.',scenario:'Logs ka ek group 365 din par hat jaata hai; invoice ki retention alag workload hai. Budget mein 1 GB = 2^30 bytes, file size KiB mein. Abhi ka data Standard → IA → Flexible; koi data phenka nahi jaata. IA transition $0.01/1,000, Flexible $0.03/1,000; archive mein har file par 40 KiB metadata. Storage ke daam lesson wale US East 2025–26 ke lagbhag rates; retrieval IA/Standard Flexible ke liye $0.01/GB + Flexible restore requests $0.05/1,000. Chhoti files default se chhoot jaati hain; override karne par penalty saaf dikhta hai. Yeh saal ka andaaza hai, bill nahi; PUT/baaki GET/transfer/KMS/replication/tax alag; ₹88 = $1.',knobs:[{id:'size',label:'Object size',min:0,max:4,step:1,value:0,labels:{0:'10 KiB',1:'128 KiB',2:'1 MiB',3:'10 MiB',4:'100 MiB'}},{id:'count',label:'Object count',min:0,max:3,step:1,value:3,labels:{0:'10,000',1:'100,000',2:'1 million',3:'10 million'}},{id:'ia',label:'IA transition age',min:15,max:90,step:15,value:30,unit:' days'},{id:'glacier',label:'Flexible transition',min:0,max:4,step:1,value:3,labels:{0:'30 days',1:'60 days',2:'90 days',3:'180 days',4:'300 days'}},{id:'reads',label:'Objects read/month',min:0,max:50,step:10,value:10,unit:'%'},{id:'override',label:'Small-size override',min:0,max:1,step:1,value:0,labels:{0:'Off / default',1:'On / force tiny'}}],model:k=>{const b=plan(k);return {readouts:[{label:'Payload preserved',value:b.gb.toFixed(1)+' GiB',tone:b.gb>=100?'ok':'bad'},{label:'Approx annual storage',value:'$'+b.storage.toFixed(2),tone:'info'},{label:'Transitions / retrieval',value:'$'+b.transitions.toFixed(2)+' / $'+b.retrieval.toFixed(2)+' per year',tone:'info'},{label:'Early-duration charge',value:'$'+b.early.toFixed(2)+'/year',tone:b.early===0?'ok':'bad'},{label:'Lagbhag saal ka kul / baseline',value:'$'+b.total.toFixed(2)+' / $'+b.baseline.toFixed(2),tone:b.saving>=0.50?'ok':'bad'},{label:'Modeled saving',value:(b.saving*100).toFixed(1)+'%',tone:b.saving>=0.50?'ok':'bad'},{label:'Config / object minimums',value:!b.eligible?'Chhoti files default se chhoot gayi':!b.valid?'Ek rule ki transition ages galat':b.noPenalty?'Minimums respected':'Small-object/early-duration penalty',tone:b.eligible&&b.valid&&b.noPenalty?'ok':'bad'}],verdict:{ok:b.ok,text:b.ok?'Data/read demand, minimums aur saal ke kharche ka goal course ke andaaze mein pass. Migration se pehle asli retrieval ka tareeka aur bill review karo.':'Example: 10 MiB × 1,00,000 files, IA 30 din, Flexible 180 din, reads 10%, override Off. Batching se lagbhag 976.6 GiB data bachta hai aur chhoti files ka overhead/handling haavi nahi hota.'}};},check:k=>plan(k).ok,lesson:'Files ka size badlo par bytes ya zaroori padhne ki demand mat khoo. 10 MiB × 1,00,000 = lagbhag 976.6 GiB; do transitions, har ek 1,00,000. Default mein 10 KiB files transition se chhoot jaati hain; chhoti files ko zabardasti bhejne se har file ke charges kul kharcha badha sakte hain. Asli aggregation format, query ka kharcha aur access badal sakta hai.'},
      {type:'bins',title:'🗂️ Workload → storage class',instructions:'Kitni baar padhna hai, retrieval ki deadline, dobara ban sakta hai ya nahi, aur minimum time: chaaron saath dekho.',bins:[{id:'standard',label:'Standard'},{id:'it',label:'Intelligent-Tiering'},{id:'ia',label:'Standard-IA'},{id:'one',label:'One Zone-IA'},{id:'instant',label:'Glacier Instant'},{id:'flex',label:'Glacier Flexible'},{id:'deep',label:'Deep Archive'}],items:[{text:'Website ki garam files, roz padhi jaati hain',bin:'standard',explain:'Baar-baar padhna; per-GB retrieval fees nahi.'},{text:'Badi files, access pata nahi ya badalta hai, online padhna chahiye',bin:'it',explain:'Eligible online auto tiers; dheeme archive sirf manzoori se.'},{text:'Kam padha jaane wala multi-AZ backup, ms reads, 30 din se zyada rakha',bin:'ia',explain:'IA latency/frequency mein theek; retrieval/minimums ka andaaza phir bhi lagao.'},{text:'Dobara ban sakne wale thumbnails, kam padhe jaate, ek AZ jaane ka khatra manzoor',bin:'one',explain:'One Zone-IA sirf recovery/khatre par sehmati ke saath.'},{text:'Teen mahine mein ek baar archive padhna, par ms mein jawaab chahiye',bin:'instant',explain:'Glacier Instant; restore wali classes nahi.'},{text:'Lamba archive, bulk restore mein 5–12 ghante chal jaayenge',bin:'flex',explain:'Flexible bulk restore theek ho sakta hai; asli capacity aur badi files ki limit review karo.'},{text:'Kai saal ka archive, sabse sasta storage rate, 12–48 ghante chal jaayenge',bin:'deep',explain:'Deep socho; 180 din ka minimum, aur restore/ready hona/retention alag.'}]},
      {type:'order',title:'🧱 Purane invoice ki compliance aur DR setup',instructions:'Config ki dependencies ko sahi order mein lagao; aakhri check ko save hue rule se mat milao.',steps:[{text:'Fixed retention, restore ki deadline aur cleanup ki manzoor limits tay karo',explain:'Asli lambi compliance retention us time tak jaan-boojh kar ulti nahi ho sakti; temporary data par jugaad mat karo.'},{text:'Source aur destination dono par versioning on hai, check karo',explain:'Object Lock aur replication version wale data par tike hain.'},{text:'Sahi Object Lock on karo; aage ke liye default aur purane version par alag retention lagao',explain:'Sirf default purane versions nahi bachata; locked source ki replication ke liye destination par lock chahiye.'},{text:'S3 trust/role ka scope, lock/KMS permissions aur destination ki ownership review karo',explain:'Config accept hone se har role/key/bucket permission pakki nahi hoti.'},{text:'Filter wali replication on karo aur nayi file ka destination/version status dekho',explain:'Purani files ke liye Batch Replication chahiye; rule ka metadata delivery nahi.'},{text:'Allowed restore/read bytes aur protected version delete ka behaviour test karo',explain:'Recovery kaam ki hai ya nahi, aur retention ka saboot, asli version/data operations se milta hai.'}]},
      {type:'triage',title:'🩺 Archive ka bill sochne se zyada',symptom:'Course fixture: 1 crore files, har ek 8 KiB. Ek saaf object-size filter ne naye small-file default ko override karke Flexible archive allow kar diya. Har file par ek transition request + archive metadata bill par haavi ho gaya.',commands:[{cmd:'aws s3api get-bucket-lifecycle-configuration --bucket tiny-logs',out:'{"TransitionDefaultMinimumObjectSize":"all_storage_classes_128K","Rules":[{"ID":"force-tiny","Status":"Enabled","Filter":{"ObjectSizeGreaterThan":0},"Transitions":[{"Days":30,"StorageClass":"GLACIER"}]}]}',clue:true,note:'Saaf size filter default ko override karta hai. Sirf naya default hota toh 128 KB se chhoti files chhoot jaati.'},{cmd:'aws s3api list-objects-v2 --bucket tiny-logs --max-keys 2',out:'{"Contents":[{"Key":"events/a.json","Size":8192,"StorageClass":"GLACIER"},{"Key":"events/b.json","Size":8192,"StorageClass":"GLACIER"}],"IsTruncated":true}',clue:true,note:'Har file ki body 8 KiB; Flexible 40 KiB metadata aur har file ki transition fees jodta hai.'},{cmd:'aws s3api get-bucket-encryption --bucket tiny-logs',out:'{"ServerSideEncryptionConfiguration":{"Rules":[{"ApplyServerSideEncryptionByDefault":{"SSEAlgorithm":"AES256"}}]}}',clue:false,note:'SSE-S3 laga hai; encryption har file ki archive handling ki wajah nahi.'},{cmd:'aws s3api get-bucket-versioning --bucket tiny-logs',out:'{}',clue:false,note:'Is cost fixture mein purane versions nahi; asli wajah file ka size aur saaf override hai.'}],questions:[Q('Model ke zyada archive bill ki sabse seedhi wajah?','Laakhon chhote transitions + har file par 40 KiB metadata, body ki bachat se zyada pade',['Naya 128 KB default bina override ke bhi saari chhoti files ka transition pakka karta hai','SSE-S3 default se har chhoti file par KMS customer-key ki fees lagata hai','Bucket versioning na hone se archive storage apne aap saat guna ho jaati hai'],0,'Saaf override ne chhote transitions chalu kiye; fees aur metadata haavi hue. Default chhoti files ko chhodta hai; SSE-S3 customer KMS nahi; versioning na hone se koi saat guna storage nahi.','cost-optimized'),Q('Logs aur kaam ka retrieval bachate hue repair kya hai?','Files jodna/compress karna, eligible size filter aur poore request/retrieval kharche ko dekho',['Retention aur batches mein saara data hai ya nahi, dekhne se pehle kachche logs turant delete karo','Public-read policy on karo, taaki har file ki archive transition fees free ho jaaye','Object Lock retention 7 saal kar do, kyunki lamba lock storage fees hata deta hai'],1,'Files jodne se har data par handling/metadata kam ho sakta hai; pehle data/index/retention check karo. Delete karne se saboot kho jaata hai, public access daam nahi badalta, aur lamba lock bacha hua kharcha badha sakta hai.','cost-optimized')]},
      (function(){const tasks=[{text:'Sirf logs ka lifecycle: size wale jode hue transitions + purane versions ka cleanup + 7 din mein adhoore uploads abort',check:lifecycle},{text:'Aage ke invoices par 7 saal compliance default AUR pehle wala v-keep kam se kam 2033-10-26 tak retain',check:protectedInvoice},{text:'Destination par versioning + Object Lock aur scoped invoice CRR metadata set',check:replication},{text:'Photo pehle se Intelligent-Tiering class mein + 180/365 din ka archive config bana raha',check:tiering},{text:'Saare asli versions, dikhne wala data, chaaron private encrypted buckets/BPA aur role bache rahe',check:preserved}];return {type:'terminal',title:'🖥️ Mission: protected asli files khoye bina archive config',instructions:'ls aur cat se saat JSON files dekho. Source invoice bucket pehle se versioned hai; destination nahi. Role-policy fixture pehle se review hua hai; role-policy.json dekho. Pehle se bana invoice key/version: invoices/INV-301.pdf / v-keep. Saat state badalne wale commands chahiye; saari API syntax asli hai.',goal:'Logs ka lifecycle sirf shop-logs par set karo; kachcha aur joda hua data bachao. Source invoice par default COMPLIANCE Years 7 AUR v-keep par alag retention ≥2033-10-26 lagao. DR par versioning aur Object Lock on karo, phir pehle se bane scoped role se filter wali replication. Media photo pehle se INTELLIGENT_TIERING hai; optional 180/365 din ke tiers set karo. Koi public access nahi, asli files delete/chhupi nahi, aur koi version bina protection nahi. Fixture ki date 2026-10-26; sirf config hai, asli aging ya replica copies ka daava nahi.',account:seed(),files:{'lifecycle.json':file(LC()),'lock-seven-years.json':file(LOCK()),'existing-invoice-retention.json':file(RETENTION()),'dr-lock.json':file({ObjectLockEnabled:'Enabled'}),'replication.json':file(REPL()),'tiering.json':file(IT()),'role-policy.json':file({Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['s3:GetReplicationConfiguration','s3:ListBucket'],Resource:'arn:aws:s3:::shop-invoices'},{Effect:'Allow',Action:['s3:GetObjectVersionForReplication','s3:GetObjectVersionAcl','s3:GetObjectVersionTagging','s3:GetObjectRetention','s3:GetObjectLegalHold'],Resource:'arn:aws:s3:::shop-invoices/invoices/*'},{Effect:'Allow',Action:['s3:ReplicateObject','s3:ReplicateDelete','s3:ReplicateTags'],Resource:'arn:aws:s3:::shop-invoices-dr/invoices/*'}]})},tasks,success:AG.allOf(tasks),solution:SOLUTION.slice(),hints:SOLUTION.map((c,i)=>c+[' — ishara: pehle destination ki zaroorat poori karo',' — invoice ki retention ko logs ke cleanup se alag rakho; teeno rules padho',' — default sirf naye versions ke liye; pehle wale v-keep ko alag retention chahiye',' — dhyaan do: exact purane version ko target karo, sirf bucket default nahi',' — locked source ki replication ke liye destination bhi locked chahiye',' — rule set hona purana backfill ya dikhi hui replica nahi hai',' — aakhri metadata: media class pehle se eligible; sirf optional archive thresholds'][i]),successText:'Asli versions bache aur dikh rahe hain; invoice ka default aur purane version ki compliance, scoped replication ki zarooratein, safe logs lifecycle aur media tiering ka metadata match karte hain. Asli replica status, lifecycle ka chalna, bill aur archive ka asli time alag saboot hain.'};})(),
      {type:'docker',title:'🐳 Lab12: locked deletes aur restore hue bytes',project:'12-s3-lifecycle-lock-replication',goal:'README ke ex1–ex5: zarooratein → lifecycle/replication metadata → governance/legal hold/marker → archive GET/restore/bytes compare → sirf apne resources ka cleanup.',why:'Kuch asli metadata/data operations check hue; Moto ki tiering/size-filter/replication ki kamiyan saaf likhi hain. Lab cleanup ke liye safe 1 din ki governance use karti hai, 7 saal ki ulti na ho sakne wali compliance nahi.',steps:[{text:'README ka alag environment, phir lab ke buckets/role. Source shuru mein unversioned hai.',cmd:'cd aws-gurukul/docker-labs\n./start-moto.sh\nsource env.sh\ncd 12-s3-lifecycle-lock-replication\n# README Setup exports run karo.\nbash setup.sh\nsource .lab/resources.sh',expect:'Source shuru mein unversioned; versioning se pehle replication ka example InvalidRequest deta hai.'},{text:'Input files padho, phir asli metadata/protection/restore exercises chalao.',cmd:'cat lifecycle.json\nbash exercises.sh\nsource .lab/resources.sh',expect:'Lifecycle/replication save hote hain; Moto saaf size filter gira deta hai, tiering put error deta hai aur get khaali aata hai. Protected version delete par AccessDenied; legal hold bhi bypass rokta hai.'},{text:'Exact version aur archive restore ki temporary state dekho; restore hue bytes compare karo.',cmd:'aws s3api head-object --bucket "$SRC" --key archive/history.txt --version-id "$ARCHIVE_VERSION"\ncmp .lab/invoice.txt .lab/restored.txt',expect:'StorageClass GLACIER; Moto mein Restore ongoing-request="false" turant; cmp exit 0.'},{text:'Cleanup padho, sirf save kiye lab resources hatao.',cmd:'bash cleanup.sh',expect:'Do khaali lists: save kiye bucket names aur IAM role nahi bache. Koi shared reset nahi.'}],observe:Q('Moto replication save karta hai par DR khaali hai; restore turant hota hai aur byte cmp pass. Saboot kya hai?','Config, protected delete aur restore ke bytes pakke; asli replication ya restore time ka saboot nahi',['Har purani file aur aage ki har write ki cross-region zero-RPO delivery naap li gayi','Byte recovery fail hui, kyunki temporary restore copy ko class hamesha ke liye badalni padti hai','Har chhoti file ka auto-tier move pakka hua, kyunki khaali tiering get ka matlab on hai'],2,'Metadata aur local restore ke asli bytes/protected deletes check hue. Replication worker, time ya auto-tier ka saboot nahi; temporary copy GLACIER reh sakti hai; khaali config ka matlab tiering set hona nahi.','resilient')},
      {type:'quiz',title:'📝 Bonus: S3 ka kharcha, retention aur recovery ki shartein',questions:[
        Q('Access pata nahi/badalta hai, files 128 KB se badi, online padhna chahiye. Kya chunoge?','Intelligent-Tiering ke online tiers; dheeme optional archive tiers ke liye alag manzoori',['Turant Glacier Deep Archive, kyunki har anjaana read apne aap 48 ghante ruk sakta hai','Har asli file ke liye One Zone-IA, kyunki access pata nahi matlab sab dobara ban sakta hai','Standard-IA, zero retrieval fees aur bina minimum time ke, roz kabhi bhi delete karne ke liye'],0,'Intelligent-Tiering eligible files ke online tiers apne aap chalata hai. Deep ki der maani nahi ja sakti; dobara banna alag baat hai; IA mein read fees/minimums hain.','cost-optimized'),
        Q('Invoice bucket default compliance Years 7 se pehle ka tha. Aur kya chahiye?','Us khaas purane version par retention lagao/check karo, ya review ki hui batch retention use karo',['Ek DNS TTL ruko, kyunki bucket defaults saare purane versions ko peeche jaa kar seal karte hain','Invoice ko Deep Archive mein daalo, kyunki storage class ka naam apne aap compliance WORM deta hai','Versioning band karo, taaki aage ke version IDs default invoice rule ko bypass na karein'],1,'Default naye versions par lagta hai; purane version ko alag/batch retention chahiye. DNS ka lena-dena nahi; class WORM nahi; Object Lock bucket mein versioning suspend nahi hoti.','secure'),
        Q('Role ARN hote hue bhi locked source ka replication rule fail ho raha hai. Destination ki kya zaroorat hai?','Destination par versioning aur Object Lock on karo; retention/legal-hold padhne ki permissions do',['Destination public karo, taaki CloudFront bina role ke cross-region replica files likh sake','Source versioning band karo, taaki ek bina naam ki file lock metadata ke bina copy ho sake','Lifecycle Expiration rule jodo, taaki har replication se pehle source ki retention hat jaaye'],2,'Locked source ko locked/versioned destination aur lock padhne ki extra permissions chahiye. Public access ka lena-dena nahi aur unsafe hai; source versioning zaroori hai; lifecycle active retention nahi hataata.','resilient'),
        Q('1 crore 8 KB files zabardasti Flexible archive mein bheji. Bachat kyun gayab ho sakti hai?','Har file ki transition requests aur har file par 40 KB metadata chhoti body ki storage par haavi',['Flexible Retrieval har case mein har file par exactly 128 KB ka 30 din ka minimum leta hai','Har S3 GET apne aap saare AWS Regions mein saat poore size ki permanent replicas banata hai','Bucket ki default encryption saari archive requests ko customer-managed KMS operations bana deti hai'],3,'Flexible ka metadata/handling maayne rakhta hai; uska minimum 90 din aur 40 KB metadata IA ke 128 KB/30 din se alag hai. GET global replicas nahi banata; SSE-S3 apne aap CMK nahi.','cost-optimized'),
        Q('Teen mahine mein ek baar archive padhna ms mein chahiye, aur 90 din se zyada rakhna hai. Class?','Glacier Instant Retrieval, retrieval fees aur 128 KB ke minimum billed size ka review karke',['Glacier Flexible Retrieval, kyunki Standard restore hamesha aam GET se pehle poora ho jaata hai','Deep Archive, kyunki sabse sasta storage hone se online jaisi read latency pakki milti hai','One Zone-IA, kyunki teen mahine wale har archive mein asli files kho dena manzoor hai'],0,'Glacier Instant ms wale archive access mein theek hai; fees/minimums maayne rakhte hain. Flexible/Deep files ko restore chahiye; ek zone wali durability ke liye recovery par alag sehmati chahiye.','high-performing'),
        Q('Bina version ID ke DELETE ne compliance-locked invoice chhupa diya. Kya hua?','Delete marker current ban sakta hai, jabki protected data version neeche bacha rehta hai',['Compliance retention bypass ho gayi, kyunki caller ne jaan-boojh kar version ID nahi diya','S3 ne saari purani retention dates ko delete request ke time tak apne aap chhota kar diya','Object Lock naye markers nahi banne deta, isliye asli file hamesha ke liye delete hi hui'],1,'Simple delete marker jod sakta hai; protected version bacha rehta hai aur permission ke saath version se padha ja sakta hai. Na bypass hua, na retention chhoti hui; marker banana allowed hai.','secure'),
        Q('Aaj live replication on hui; kal ke invoices DR mein nahi hain. Kaunsa workflow chahiye?','Purani eligible files ke liye review kiya S3 Batch Replication, phir destination ka data check',['15 minute ruko, kyunki RTC nayi writes se pehle saari purani files backfill karta hai','Lifecycle transition age kam karo, taaki purana data apne aap naya replication traffic ban jaaye','Intelligent-Tiering monitoring on karo, kyunki monitor ki fees mein purani DR copying bhi aati hai'],2,'Live replication purana backfill nahi hai; purane data ke liye Batch Replication hai. RTC ka time nayi eligible replication ke liye hai; lifecycle/tiering backfill ki guarantee nahi dete.','resilient'),
        Q('Archive restore request accept ho gayi. Recovery kab bol sakte hain?','Restore state poori hone aur permissions ke saath read/version/body checks pass hone ke baad',['Request par 202 aate hi, kyunki saari archive classes hamesha ke liye Standard ban jaati hain','Jab get-bucket-replication role ARN dikhaye, chahe archive GET abhi bhi deny ho raha ho','Object Lock on karne ke baad, kyunki bache hue encrypted bytes hamesha turant padhe ja sakte hain'],3,'Restore accept hona poora hona nahi; data padh kar version/content check karo. Temporary restore asli class nahi badalta; replication config/lock archive bytes ko turant padhne layak nahi banate.','resilient'),
      ]},
    ],
    interview:{title:'🎤 Storage architecture aur restore ka saboot',instructions:'Kul kharcha, version ki protection aur asli recovery ka saboot chuno. Aakhri CLI kaam model ka restore poora hone ke baad exact archive version padhta hai.',questions:[
      Q('Ek rule mein Standard → IA 15 din → Flexible 30 din maanga gaya. Sabse achha review?','Galat IA age/gap reject karo; sahi transitions aur minimum-time ka budget dobara banao',['Approve karo, kyunki har storage class ka minimum sirf saaf bucket deletion par lagta hai','Approve karo, kyunki Flexible ka 90 din ka minimum pehle ki har IA billing ki shart hata deta hai','Versioning hata do, kyunki lifecycle transition rules sirf unversioned buckets par chalte hain'],0,'IA ki lifecycle age kam se kam 30 din honi chahiye, aur ek rule ki chain source ka minimum time maane. Minimums transitions/deletion par asar daalte hain; versioning lifecycle ko nahi rokti.','cost-optimized'),
      Q('Governance bypass permission + flag hai, aur legal hold ON hai. Kya protected version delete ho sakta hai?','Nahi; legal hold alag hai, governance bypass ke kaam aane se pehle allowed OFF chahiye',['Haan; bypass flag har retained version par legal hold aur compliance dono ko override karta hai','Haan; legal hold sirf bucket ke naam par lagta hai, kabhi alag file versions par nahi','Nahi; governance kabhi bypass nahi hoti, chahe permission aur saaf request flag ho'],1,'Legal hold alag rehta hai. Governance sahi permission + flag se bypass ho sakti hai; hold version level par hai aur compliance us flag se bypass nahi hoti.','secure'),
      Q('Source par Object Lock on hai; KMS key nasht ho gayi. Ab kya guarantee bachti hai?','Version delete se bachav encryption key ke bina decrypt/padh kar recovery pakki nahi karta',['S3 apne aap plaintext wapas deta hai, kyunki Object Lock ek doosri bina encryption copy rakhta hai','RTC kisi bhi archive file ko padhne se pehle har kho chuki customer key turant dobara bana deta hai','Deep Archive key-policy denial ko override karta hai, isliye compliance audit hamesha plaintext deta hai'],2,'Retention aur key ka milna alag baatein hain. Plaintext ya key apne aap wapas nahi aati; RTC config ke hisaab se eligible files copy karta hai, khoyi keys nahi; archive key policy override nahi karta.','resilient'),
      Q('Bahut zyada requests: har prefix ke 3,500 writes/5,500 reads ko kaise samjhein?','Har prefix par kam se kam itna scale; kaam parallel karo, dheere scaling aur retries sambhalo',['Poore bucket ki pakki maximum limit, jo kai prefixes ya clients se bhi nahi badhti','Har file ke liye pakka fixed request rate, workload scale hone se pehle bhi','Encryption ki shart jo saare prefixes ko ek hi customer-managed KMS key par majboor kare'],3,'AWS har prefix par "kam se kam" performance likhta hai; scaling dheere hoti hai aur workload se badalti hai. Yeh na bucket ki fixed limit hai, na har file ki guarantee; KMS quotas alag rukawat ho sakte hain, par ek hi key zaroori nahi.','high-performing'),
      {terminal:(function(){const a=seed(),b=a.buckets.find(b=>b.name==='shop-logs'),body='dummy audit source';b.versions['archive/audit.txt']=[{versionId:'v-archive',storageClass:'GLACIER',body,size:body.length,etag:'"audit-v1"'}];const tasks=[{text:'Exact archive v-archive abhi bhi GLACIER; saaf polls ke baad restore poora aur expire nahi hua',check:s=>{const v=version(s,'shop-logs','archive/audit.txt','v-archive');return !!v&&v.storageClass==='GLACIER'&&v.restore&&v.restore.pollsRemaining===0&&new Date(v.restore.expires)>new Date(NOW)&&v.body===body;}},{text:'Output mein exact archive version/body/etag hai, sirf GET likh dena nahi',check:s=>{const d=s.downloads&&s.downloads['audit-restored.txt'];return !!d&&d.versionId==='v-archive'&&d.body===body&&d.etag==='"audit-v1"';}},{text:'Asli invoices/logs/media, private buckets aur role bache rahe',check:preserved}];const solution=['aws s3api restore-object --bucket shop-logs --key archive/audit.txt --version-id v-archive --restore-request file://restore.json','aws s3api head-object --bucket shop-logs --key archive/audit.txt --version-id v-archive','aws s3api head-object --bucket shop-logs --key archive/audit.txt --version-id v-archive','aws s3api get-object --bucket shop-logs --key archive/audit.txt --version-id v-archive audit-restored.txt'];return {title:'🖥️ Archive audit: restore, poll aur exact version check',goal:'archive/audit.txt / v-archive GLACIER mein hai. cat restore.json chalao, Standard tier mein 2 din ke liye restore karo. Model mein do head-object polls chahiye (pehla ongoing=true, doosra false). AWS ke asli minute/ghante simulate nahi hote, aur S3 ka koi restore-completed waiter nahi. Phir exact version audit-restored.txt mein lo; yeh memory mein bana output hai, aur body/version/etag check hote hain. Asli file delete/dobara upload mat karo, na koi naya Standard object badle mein rakho.',account:a,files:{'restore.json':file({Days:2,GlacierJobParameters:{Tier:'Standard'}})},tasks,success:AG.allOf(tasks),solution,hints:solution.map((c,i)=>c+[' — asli restore request bhejo, storage class ka naam badalna nahi',' — pehli baar dekhne par model mein ongoing-request=true',' — doosri baar dekhne par fixture poora ho jaata hai; asli time ka daava nahi',' — aakhri recovery read output mein asli version/body bharta hai'][i]),successText:'Exact v-archive restore ho kar padha gaya; memory wale output mein body="dummy audit source", etag="audit-v1". Asli file GLACIER mein hi hai, aur restore wali copy expire hogi. Poll ki ginti course ka step hai; Moto lab local restore ke asli bytes alag se check karti hai.'};})()},
    ]},
    success:['Storage class, file ka size aur kul request/read/minimum kharche compare kar sakta hoon','Bucket default vs purane version ki compliance/legal hold aur delete markers samjha sakta hoon','Replication ki zarooratein/config aur asli DR delivery ka farak bata sakta hoon','Archive restore ka ready hona aur exact version/body ka saboot check kar sakta hoon'],
    homework:'<p><b>Optional, sirf approved asli AWS sandbox mein (paisa lagega, retention dhyaan se):</b> pehle region, files ki ginti, read, transition, restore, replication aur KMS ka kharcha nikaalo. Chhota temporary data set use karo, inventory/checksums ke saath. Lifecycle config test karo, mahino wait kiye bina, aur turant move hone ka daava mat karo. Cleanup ke liye chhoti GOVERNANCE retention aur bypass permissions manzoor karwao. Temporary asli resources par 7 saal ki COMPLIANCE mat lagao. Purane version ki retention aur aage ki default retention alag dekho. Versioned destination/lock/role/key ki zarooratein review karo; ek approved nayi file upload karke replication status aur destination ke bytes check karo; purane data ke liye Batch Replication. Archive sirf ek approved file karo, wo bhi tab jab restore ki der aur kharcha manzoor ho; asli Restore metadata poll karo, exact version aur bytes check karo. Cleanup: legal holds sirf manzoori se hatao, governance sirf allowed flag se bypass karo, exact versions/markers/adhoore uploads, bucket ki replication/tiering/lifecycle settings, test buckets aur scoped role/policies hatao. Active COMPLIANCE cleanup ke liye bypass nahi hoti; bachai gayi keys aur shared data ko mat chhuo.</p>',
    cards:[{front:'IA vs Glacier ke minimums?',back:'IA/One Zone-IA: 30 din aur 128 KB minimum billed size. Glacier Instant: 90 din/128 KB. Flexible 90 din aur Deep 180 din; dono har file par 40 KB metadata jodte hain (8 KB Standard + 32 KB archive). Har file/request/read ki fees maayne rakhti hai.'},{front:'Intelligent-Tiering small objects?',back:'128 KB se chhoti files Frequent tier mein rehti hain: na monitoring charge, na auto-tier. Online tiers 30/90 din; dheeme archives ke liye saaf config chahiye. Sirf config bana dene se Standard files convert nahi hoti.'},{front:'Naye lifecycle mein chhoti files ka default?',back:'September 2024 se naye/update hue configs default mein 128 KB se chhoti files ka transition chhod dete hain. Saaf size filter isko override kar sakta hai. Files jodne se metadata/request ka kharcha kam ho sakta hai, agar data/read/index ki zarooratein bani rahein.'},{front:'7 saal ki default retention purane invoice ko bachati hai?',back:'Nahi. Default naye versions par lagta hai. Purane version par alag ya batch retention lagao/check karo; active retention mein compliance ko koi, root bhi, chhota ya delete nahi kar sakta.'},{front:'Delete marker vs protected version?',back:'Simple DELETE marker se latest key chhupa sakta hai; retained version bacha rehta hai. Naye versions ban sakte hain. Governance bypass compliance/legal hold ko override nahi karta.'},{front:'Replication rule DR ka saboot hai?',back:'Nahi. Versioning/role/lock/KMS ki zarooratein poori karo, nayi file ka destination status/data asal mein dekho. Purani files ke liye Batch Replication; RTC SLA scope mein 99.99% files 15 min mein, zero RPO nahi.'},{front:'Restore accept hua: kya file ab Standard hai?',back:'Nahi. Flexible/Deep mein restore poora hone par thodi der ki padhne layak copy milti hai; asli archive class wahi rehti hai. Asli state poll karo, recovery bolne se pehle exact version/bytes padho.'},{front:'Upload/performance ke aaj ke numbers?',back:'Har partitioned prefix par kam se kam 3,500 write/5,500 read requests/second, scaling dheere-dheere. Multipart 100 MB+ par socho, 5 GB se upar zaroori; December 2025 se maximum 50 TB likha hai, purana 5 TB nahi.'}],
  }]);
})();
